import {validateStore,fixtureTypes,DEFAULT_STORE} from './store-schema.js';
import {savedStores,saveStore,syncStoreLibrary,shareStore,switchStore,cloud} from './store-context.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const types={wall:'의류 행거',cap_wall:'모자 벽장',cap_island:'모자 아일랜드',shoe_wall:'슈즈장',bag_wall:'가방 벽장',table:'상품 테이블',mannequin:'마네킹 구역'};
const field=(name,label,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function exportConfig(store){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(store,null,2)],{type:'application/json'}));link.download=store.id+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)}
export function initStoreManager({context,modal,toast,products}){
  const button=document.createElement('button');button.id='store-manager';button.className='secondary-btn store-manager-button';button.textContent='매장 전환 · 관리';document.querySelector('.store-title').after(button);
  const mobile=document.createElement('button');mobile.className='mobile-store-manager';mobile.textContent='매장 관리';document.querySelector('.toolbar-actions').prepend(mobile);mobile.onclick=button.onclick=show;
  async function show(){
    try{await syncStoreLibrary();const stores=await savedStores();
      modal('담당 매장',`<p class="dialog-description">매장별 도면·집기·재고·업무를 분리합니다. 개인 설정은 이 브라우저(IndexedDB)에 저장되며, 공유한 설정과 현장 업무는 팀의 Supabase 공간에 저장됩니다.</p><div class="store-library"><article><span class="store-tag">참고 매장</span><h3>공개 샘플 매장</h3><p>직접 생성한 샘플 공간 · 합성 재고</p><button class="primary-btn" data-open-store="myeongdong">매장 열기</button></article>${stores.map(s=>`<article><span class="store-tag">${s.dirty?'이 기기에 저장':s.revision?'팀에 공유됨':'이 기기에 저장'}</span><h3>${esc(s.name)}</h3><p>${esc(s.floorLabel)} · ${s.widthMm/1000} × ${s.depthMm/1000}m · 집기 ${s.fixtures.length}개</p><button class="primary-btn" data-open-store="${s.id}">매장 열기</button><div class="store-card-actions"><button data-edit-store="${s.id}">설정</button><button data-export-store="${s.id}">JSON 내보내기</button><button data-share-store="${s.id}" ${cloud.authorized?'':'disabled'}>팀에 공유</button></div></article>`).join('')}</div><div class="dialog-actions"><label class="secondary-btn">설정 JSON 가져오기<input id="import-store" type="file" accept="application/json,.json" hidden></label><button id="new-store" class="primary-btn">+ 새 매장 등록</button></div><p class="record-note">${cloud.publicDemo?'공개 시연 모드입니다. 팀에 공유한 설정은 링크로 접속한 누구나 볼 수 있습니다.':'팀 공유는 초대 링크 참여 후 사용할 수 있습니다.'} 현재는 팀 공동 시연 공간이며 개인별 접근 권한 기능은 아직 제공하지 않습니다. NTS 도면 이미지는 축척으로 간주하지 않습니다.</p>`,'STORE LIBRARY');
      document.querySelectorAll('[data-open-store]').forEach(b=>b.onclick=()=>switchStore(b.dataset.openStore));
      document.querySelectorAll('[data-edit-store]').forEach(b=>b.onclick=()=>edit(stores.find(s=>s.id===b.dataset.editStore)));
      document.querySelectorAll('[data-export-store]').forEach(b=>b.onclick=()=>exportConfig(stores.find(s=>s.id===b.dataset.exportStore)));
      document.querySelectorAll('[data-share-store]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await shareStore(stores.find(s=>s.id===b.dataset.shareStore));toast('매장 설정을 팀에 공유했습니다.');await show()}catch(e){toast(e.message);b.disabled=false}});
      document.querySelector('#new-store').onclick=()=>edit({id:'store-'+crypto.randomUUID().slice(0,8),name:'새 매장',floorLabel:'1F',widthMm:8000,depthMm:10000,heightMm:3200,originMm:[4000,0],rotationDeg:0,fixtures:[{id:'F-01',label:'첫 번째 진열장',type:'cap_wall',xMm:1000,yMm:6000,widthMm:2400,depthMm:500,heightMm:2200,rotationDeg:0,capacity:24,fixed:true}],assortment:[],display:[]});
      document.querySelector('#import-store').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2100000)throw Error('설정 파일은 2MB 이하로 선택하세요.');const config=validateStore(JSON.parse(await file.text()));const existing=stores.find(s=>s.id===config.id);if(existing)throw Error('같은 ID의 매장이 있습니다. 기존 설정에서 수정하세요.');await edit({...config,revision:0})}catch(e){toast(e.message)}};
    }catch(e){toast(e.message)}
  }
  async function edit(original){
    const store=structuredClone(original);let planImage=store.planImage||'';
    modal('매장 공간 설정',`<form id="store-form"><div class="store-settings-grid">${field('name','매장 이름',store.name)}${field('floorLabel','층',store.floorLabel)}${field('widthMm','가로 폭 (mm)',store.widthMm,'number','min="2000" max="100000" required')}${field('depthMm','세로 깊이 (mm)',store.depthMm,'number','min="2000" max="100000" required')}${field('heightMm','층 높이 (mm)',store.heightMm,'number','min="2000" max="10000" required')}${field('originX','원점 X (mm)',store.originMm[0],'number')}${field('originY','원점 Y (mm)',store.originMm[1],'number')}${field('rotationDeg','도면 회전 (°)',store.rotationDeg,'number')}</div><div class="floor-editor"><div><div id="floor-preview"></div><label class="secondary-btn">도면 이미지 선택<input id="store-floor-image" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><button type="button" id="remove-floor-image">이미지 제거</button><p class="record-note">1MB 이하 JPG·PNG·WebP. 이미지는 입력한 매장 크기에 맞춘 참고 배경입니다. NTS 그림에서 실측을 추정하지 않습니다. 원점과 회전은 mm 좌표에 적용됩니다.</p></div><div><h3>집기 배치</h3><p class="dialog-description">도면 좌측 상단 기준 X·Y, 실제 폭·깊이·높이를 입력하세요.</p><div id="store-fixtures"></div><button type="button" id="add-fixture" class="secondary-btn">+ 집기 추가</button></div></div><details class="store-stock"><summary>상품·재고·진열 설정</summary><p class="record-note">상품 ID는 현재 제공된 카탈로그에서 선택합니다. 입력한 재고는 이 매장에서만 사용합니다.</p><button type="button" id="sample-assortment" class="secondary-btn">시연용 상품 4종 채우기</button><div class="form-grid"><label>재고: 상품ID, 총재고, 예약, 판매불가<textarea id="store-assortment" rows="6">${esc(store.assortment.map(p=>[p.productId,p.onHandQty,p.reservedQty,p.unsellableQty].join(',')).join('\n'))}</textarea></label><label>진열: 집기ID, 상품ID, 수량<textarea id="store-display" rows="6">${esc(store.display.map(p=>[p.fixture,p.productId,p.quantity].join(',')).join('\n'))}</textarea></label></div><p class="record-note">예: HAT-001,20,0,0 / F-01,HAT-001,6. 원본 상품 사진과 모델 종류를 재사용하는 시연 카탈로그입니다.</p></details><p id="store-form-error" role="alert"></p><div class="dialog-actions"><button type="button" id="back-stores">돌아가기</button><button class="primary-btn" type="submit">설정 저장 후 매장 열기</button></div></form>`,'FLOORPLAN / MILLIMETRES');
    document.querySelector('#dialog').classList.add('wide-dialog');
    document.querySelector('#dialog').addEventListener('close',()=>document.querySelector('#dialog').classList.remove('wide-dialog'),{once:true});
    const form=document.querySelector('#store-form');
    function readFixtures(){return[...document.querySelectorAll('.store-fixture-edit')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-f]')].map(input=>[input.dataset.f,input.type==='number'?Number(input.value):input.type==='checkbox'?input.checked:input.value])))}
    function draw(){const width=Number(form.elements.widthMm.value)||8000,depth=Number(form.elements.depthMm.value)||10000,fixtures=readFixtures();document.querySelector('#floor-preview').innerHTML=`<svg viewBox="0 0 ${width} ${depth}" aria-label="mm 치수 기반 집기 도면"><rect width="${width}" height="${depth}" fill="#eeeee8"/>${planImage?`<image href="${planImage}" width="${width}" height="${depth}" preserveAspectRatio="none" opacity=".55"/>`:''}${fixtures.map(f=>`<g transform="rotate(${f.rotationDeg},${f.xMm+f.widthMm/2},${f.yMm+f.depthMm/2})"><rect x="${f.xMm}" y="${f.yMm}" width="${f.widthMm}" height="${f.depthMm}" rx="30" fill="#507e6d" opacity=".85"/><text x="${f.xMm+f.widthMm/2}" y="${f.yMm+f.depthMm/2}" text-anchor="middle" dominant-baseline="middle" fill="white" font-size="${width/38}">${esc(f.id)}</text></g>`).join('')}<circle cx="${Number(form.elements.originX.value)}" cy="${Number(form.elements.originY.value)}" r="${width/70}" fill="#d29238"/></svg>`}
    function renderFixtures(rows){document.querySelector('#store-fixtures').innerHTML=rows.map((f,i)=>`<div class="store-fixture-edit"><div class="fixture-edit-heading"><strong>집기 ${i+1}</strong><button type="button" data-remove-fixture="${i}" aria-label="집기 ${i+1} 삭제">×</button></div><div class="store-settings-grid">${[['id','ID'],['label','이름']].map(([k,l])=>`<label>${l}<input data-f="${k}" value="${esc(f[k])}" required></label>`).join('')}<label>종류<select data-f="type">${fixtureTypes.map(t=>`<option value="${t}" ${f.type===t?'selected':''}>${types[t]}</option>`).join('')}</select></label>${[['xMm','X mm'],['yMm','Y mm'],['widthMm','폭 mm'],['depthMm','깊이 mm'],['heightMm','높이 mm'],['rotationDeg','회전 °'],['capacity','진열 한도']].map(([k,l])=>`<label>${l}<input type="number" data-f="${k}" value="${f[k]??0}" required></label>`).join('')}<label>고정 집기<input data-f="fixed" type="checkbox" ${f.fixed?'checked':''}></label></div></div>`).join('');document.querySelectorAll('[data-remove-fixture]').forEach(b=>b.onclick=()=>{const rows=readFixtures();rows.splice(Number(b.dataset.removeFixture),1);renderFixtures(rows);draw()});draw()}
    renderFixtures(store.fixtures);form.addEventListener('input',draw);
    document.querySelector('#add-fixture').onclick=()=>{const rows=readFixtures();let i=rows.length+1;while(rows.some(r=>r.id==='F-'+String(i).padStart(2,'0')))i++;rows.push({id:'F-'+String(i).padStart(2,'0'),label:'새 진열장',type:'table',xMm:1000,yMm:2000,widthMm:1600,depthMm:600,heightMm:900,rotationDeg:0,capacity:12,fixed:false});renderFixtures(rows)};
    document.querySelector('#store-floor-image').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000||!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('1MB 이하 도면 이미지를 선택하세요.');return}planImage=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});draw()};
    document.querySelector('#remove-floor-image').onclick=()=>{planImage='';draw()};document.querySelector('#back-stores').onclick=show;
    document.querySelector('#sample-assortment').onclick=()=>{document.querySelector('#store-assortment').value='HAT-001,20,0,0\nSHO-003,12,0,0\nOUT-004,12,0,0\nBAG-001,8,0,0';const first=readFixtures()[0]?.id;if(first)document.querySelector('#store-display').value=first+',HAT-001,6';toast('예시 재고입니다. 실제 수량으로 수정하세요.')};
    form.onsubmit=async e=>{e.preventDefault();try{const f=new FormData(form),lines=id=>document.querySelector(id).value.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>l.split(',').map(v=>v.trim()));const assortment=lines('#store-assortment').map(([productId,q,r=0,u=0])=>({productId,onHandQty:Number(q),reservedQty:Number(r),unsellableQty:Number(u)}));for(const p of assortment)if(!products.some(x=>x.product_id===p.productId))throw Error('카탈로그에 없는 상품 ID: '+p.productId);const display=lines('#store-display').map(([fixture,productId,quantity])=>({fixture,productId,quantity:Number(quantity)}));
      const changedSize=Number(f.get('widthMm'))!==store.widthMm||Number(f.get('depthMm'))!==store.depthMm;
      const config=validateStore({...store,name:f.get('name'),floorLabel:f.get('floorLabel'),widthMm:Number(f.get('widthMm')),depthMm:Number(f.get('depthMm')),heightMm:Number(f.get('heightMm')),originMm:[Number(f.get('originX')),Number(f.get('originY'))],rotationDeg:Number(f.get('rotationDeg')),outlineMm:changedSize?undefined:store.outlineMm,planImage,fixtures:readFixtures(),assortment,display});await saveStore({...config,revision:store.revision??0,dirty:true});switchStore(config.id);
    }catch(e){document.querySelector('#store-form-error').textContent=e.message}};
  }
  return{show};
}
